122	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
123	    @Override
124	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
125	        normalizeAddress(ownerFieldsDto);
126	        validateRequiredFields(ownerFieldsDto);
127	        normalizeTelephone(ownerFieldsDto);
128	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
129	        rejectDuplicateHousehold(ownerFieldsDto);
130	        rejectCityAtCapacity(ownerFieldsDto.getCity());
131	        defaultRegistrationDate(ownerFieldsDto);
132	        rejectDailyLimit(ownerFieldsDto.getRegistrationDate());
133	        normalizeEmail(ownerFieldsDto);
134	        rejectDuplicateEmail(ownerFieldsDto.getEmail());
135	        HttpHeaders headers = new HttpHeaders();
136	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
137	        assignCustomerCode(owner);
138	        assignHouseholdId(owner);
139	        assignHouseholdMemberCount(owner);
140	        assignNamesakeCount(owner);
141	        assignMembershipNumber(owner);
142	        assignBulkSignupWarning(owner);
143	        this.clinicService.saveOwner(owner);
144	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
145	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
146	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
147	        headers.setLocation(UriComponentsBuilder.newInstance()
148	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
149	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
150	    }
