234	    /**
235	     * Rejects an owner whose mandatory fields ({@code firstName}, {@code lastName},
236	     * {@code address}, {@code city}, {@code telephone}) are missing or blank. Bean
237	     * Validation already rejects {@code null} values and the pattern-constrained fields
238	     * when blank, but {@code address} and {@code city} have no pattern, so a
239	     * whitespace-only value would otherwise slip through.
240	     *
241	     * @param ownerFieldsDto the submitted owner fields
242	     * @throws RequiredFieldsMissingException if any required field is missing or blank
243	     */
244	    /**
245	     * Common street-type abbreviations expanded during address normalization. Keys are the
246	     * upper-cased abbreviation tokens; values are their canonical expansions.
247	     */
248	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
249	        "ST", "STREET",
250	        "RD", "ROAD",
251	        "AVE", "AVENUE");
252	
253	    /**
254	     * Normalizes the submitted address on create and writes the canonical value back onto the
255	     * request so it is persisted, echoed back, and used for every downstream address comparison
256	     * (household duplicate detection and the household id). The value is trimmed, internal
257	     * whitespace runs are collapsed to a single space, it is upper-cased, and common street-type
258	     * abbreviations are expanded token-by-token (see {@link #ADDRESS_ABBREVIATIONS}). A
259	     * {@code null} address is left untouched so the required-field check can report it as missing.
260	     *
261	     * @param ownerFieldsDto the submitted owner fields
262	     */
263	    private static void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
264	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
265	    }
266	
267	    /**
268	     * Canonicalizes an address value: trimmed, internal whitespace collapsed to single spaces,
269	     * upper-cased, and each whitespace-delimited token that is a known street-type abbreviation
270	     * expanded to its full form. A {@code null} value is returned unchanged.
271	     *
272	     * @param raw the address to canonicalize, possibly {@code null}
273	     * @return the normalized address, or {@code null} if {@code raw} was {@code null}
274	     */
275	    private static String normalizeAddress(String raw) {
276	        if (raw == null) {
277	            return null;
278	        }
279	        String collapsed = raw.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
280	        if (collapsed.isEmpty()) {
281	            return collapsed;
282	        }
283	        String[] tokens = collapsed.split(" ");
284	        StringBuilder sb = new StringBuilder(collapsed.length());
285	        for (int i = 0; i < tokens.length; i++) {
286	            if (i > 0) {
287	                sb.append(' ');
288	            }
289	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
290	        }
291	        return sb.toString();
292	    }
293	
294	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
295	        List<String> errors = new ArrayList<>();
296	        requireText("firstName", ownerFieldsDto.getFirstName(), errors);
297	        requireText("lastName", ownerFieldsDto.getLastName(), errors);
298	        requireText("address", ownerFieldsDto.getAddress(), errors);
299	        requireText("city", ownerFieldsDto.getCity(), errors);
300	        requireText("telephone", ownerFieldsDto.getTelephone(), errors);
301	        if (!errors.isEmpty()) {
302	            throw new RequiredFieldsMissingException(errors);
303	        }
304	    }
305	
306	    private static void requireText(String field, String value, List<String> errors) {
307	        if (value == null || value.isBlank()) {
308	            errors.add(field);
309	        }
310	    }
311	
312	    /**
313	     * Normalizes the submitted telephone on create to E.164 form (see {@link #toE164}) and
314	     * writes the canonical {@code '+'}-prefixed value back onto the request so it is persisted
315	     * and echoed back in that form.
316	     *
317	     * @param ownerFieldsDto the submitted owner fields
318	     * @throws RequiredFieldsMissingException with a 400 status if the telephone cannot form a
319	     *                                        valid E.164 number
320	     */
321	    private static void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
322	        String e164 = toE164(ownerFieldsDto.getTelephone());
323	        if (e164 == null) {
324	            throw new RequiredFieldsMissingException(List.of("telephone"));
325	        }
326	        ownerFieldsDto.setTelephone(e164);
327	    }
328	
329	    /**
330	     * Converts a raw telephone to E.164 form, or returns {@code null} when it cannot form a
331	     * valid E.164 number. Spaces, dashes and brackets are stripped. When a leading {@code '+'}
332	     * and country code are present they are kept; otherwise country code {@code '+61'} is
333	     * assumed and a single leading {@code '0'} is dropped from the national digits. The result
334	     * must contain 8 to 15 digits after the {@code '+'}, and for the recognised country codes
335	     * the national-number length must match the country: {@code '+61'} (Australia) requires
336	     * exactly 9 national digits and {@code '+1'} (NANP) requires exactly 10.
337	     *
338	     * @param raw the submitted telephone, possibly {@code null}
339	     * @return the canonical E.164 string, or {@code null} if it is not a valid E.164 number
340	     */
341	    private static String toE164(String raw) {
342	        if (raw == null) {
343	            return null;
344	        }
345	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
346	        String digits;
347	        if (cleaned.startsWith("+")) {
348	            digits = cleaned.substring(1);
349	        } else {
350	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
351	            digits = "61" + national;
352	        }
353	        if (!digits.matches("[0-9]{8,15}")) {
354	            return null;
355	        }
356	        if (digits.startsWith("61")) {
357	            // Australia: exactly 9 national digits after the '+61' country code.
358	            if (digits.length() - 2 != 9) {
359	                return null;
360	            }
361	        } else if (digits.startsWith("1")) {
362	            // NANP: exactly 10 national digits after the '+1' country code.
363	            if (digits.length() - 1 != 10) {
364	                return null;
365	            }
366	        }
367	        return "+" + digits;
368	    }
369	
370	    /**
371	     * Rejects a create whose E.164 telephone is already used by any existing owner. The
372	     * submitted telephone has already been normalized to E.164 by {@link #normalizeTelephone};
373	     * each stored owner's telephone is normalized the same way before comparison so differing
374	     * input formats collapse to the same value.
375	     *
376	     * @param normalizedTelephone the submitted, already-normalized E.164 telephone
377	     * @throws DuplicateTelephoneException with a 409 status if another owner already uses the
378	     *                                     same E.164 telephone
379	     */
380	    /**
381	     * Matches a syntactically valid email address: a non-empty local part, an {@code @},
382	     * and a domain of at least two dot-separated labels ending in an alphabetic TLD. None of
383	     * the parts may contain whitespace or a second {@code @}.
384	     */
385	    private static final Pattern EMAIL_PATTERN =
386	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}$");
387	
388	    /**
389	     * Normalizes the submitted email when present: the value is trimmed, required to be a
390	     * syntactically valid address, and written back lower-cased so it is persisted and echoed
391	     * back in canonical form. A {@code null} email is left untouched — the field is optional.
392	     *
393	     * @param ownerFieldsDto the submitted owner fields
394	     * @throws InvalidEmailException with a 400 status if the email is present but not syntactically valid
395	     */
396	    private static void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
397	        String email = ownerFieldsDto.getEmail();
398	        if (email == null) {
399	            return;
400	        }
401	        String trimmed = email.strip();
402	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
403	            throw new InvalidEmailException(email);
404	        }
405	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
406	    }
407	
408	    /**
409	     * Establishes the effective registration date on create and rolls it onto a business day.
410	     * When the client does not supply a {@code registrationDate} it defaults to the server's
411	     * current date; the resulting date (supplied or defaulted) is then rolled forward to the
412	     * next Monday when it falls on a Saturday or Sunday (see {@link #toBusinessDay}). The
413	     * adjusted value is written back onto the request so it is persisted, echoed back in ISO
414	     * 'YYYY-MM-DD' format, and used by every value derived from the registration date (such as
415	     * the membership number's year segment and the daily create-limit).
416	     *
417	     * @param ownerFieldsDto the submitted owner fields
418	     */
419	    private static void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
420	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
421	        if (effective == null) {
422	            effective = LocalDate.now();
423	        }
424	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
425	    }
426	
427	    /**
428	     * Rolls a date forward to the next business day: a Saturday or Sunday is advanced to the
429	     * following Monday; any weekday is returned unchanged.
430	     *
431	     * @param date the date to adjust
432	     * @return the same date when it is a weekday, otherwise the next Monday
433	     */
434	    private static LocalDate toBusinessDay(LocalDate date) {
435	        return switch (date.getDayOfWeek()) {
436	            case SATURDAY -> date.plusDays(2);
437	            case SUNDAY -> date.plusDays(1);
438	            default -> date;
439	        };
440	    }
441	
442	    /**
443	     * Assigns the owner's {@code customerCode} on create, formatted
444	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is the upper-cased first three letters of
445	     * {@code city}, LAST3 the upper-cased first three letters of {@code lastName}, and NNNN a
446	     * per-city 4-digit zero-padded sequence equal to one more than the number of owners already
447	     * in that city (compared case-insensitively) — e.g. {@code 'SYD-SMI-0007'}.
448	     *
449	     * @param owner the owner being created (with its {@code city} and {@code lastName} already set)
450	     */
451	    private void assignCustomerCode(Owner owner) {
452	        String city = owner.getCity();
453	        String lastName = owner.getLastName();
454	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
455	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
456	        long sequence = this.clinicService.findAllOwners().stream()
457	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
458	            .count() + 1;
459	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
460	    }
461	
462	    /**
463	     * Assigns the owner's {@code householdId} on create: a stable identifier for the household,
464	     * formatted {@code 'HH-<HEX12>'} where HEX12 is the first 12 upper-cased hex characters of the
465	     * SHA-256 digest of the owner's collapsed {@code lastName} and {@code address} (see
466	     * {@link #collapse}) joined by a {@code '\n'}. Because it is derived purely from those two
467	     * canonicalized fields, every owner in the same household — including one joining an existing
468	     * household via {@code sharesHousehold} — is assigned the same value, independent of create
469	     * order.
470	     *
471	     * @param owner the owner being created (with its {@code lastName} and {@code address} already set)
472	     */
473	    private void assignHouseholdId(Owner owner) {
474	        String key = collapse(owner.getLastName()) + "\n" + collapse(owner.getAddress());
475	        owner.setHouseholdId("HH-" + sha256Hex(key).substring(0, 12).toUpperCase(Locale.ROOT));
476	    }
477	
478	    /**
479	     * Assigns the owner's {@code householdMemberCount} on create: the number of owners in this
480	     * owner's household — those already sharing its {@code householdId} plus this owner itself —
481	     * after this create. Because {@code householdId} is derived from the owner's collapsed
482	     * {@code lastName} and {@code address} (see {@link #assignHouseholdId}), the count reflects every
483	     * owner registered to the same household, including those who joined via {@code sharesHousehold}.
484	     * The count is taken before this owner is persisted, so it is one more than the number of
485	     * existing household members.
486	     *
487	     * @param owner the owner being created (with its {@code householdId} already assigned)
488	     */
489	    private void assignHouseholdMemberCount(Owner owner) {
490	        String householdId = owner.getHouseholdId();
491	        long existing = this.clinicService.findAllOwners().stream()
492	            .filter(other -> householdId != null && householdId.equals(other.getHouseholdId()))
493	            .count();
494	        owner.setHouseholdMemberCount((int) (existing + 1));
495	    }
496	
497	    /**
498	     * Assigns the owner's {@code namesakeCount} on create: the number of existing owners that
499	     * already share this owner's {@code firstName} and {@code lastName}, compared
500	     * case-insensitively. The count is taken before this owner is persisted, so it reflects only
501	     * pre-existing namesakes.
502	     *
503	     * @param owner the owner being created (with its {@code firstName} and {@code lastName} already set)
504	     */
505	    private void assignNamesakeCount(Owner owner) {
506	        String firstName = owner.getFirstName();
507	        String lastName = owner.getLastName();
508	        long count = this.clinicService.findAllOwners().stream()
509	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
510	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
511	            .count();
512	        owner.setNamesakeCount((int) count);
513	    }
514	
515	    /**
516	     * Assigns the owner's {@code membershipNumber} on create, formatted
517	     * {@code '<customerCode>-M<YY>'} where customerCode is the owner's already-assigned customer
518	     * code and YY is the last two digits of the {@code registrationDate} year, zero-padded
519	     * (e.g. {@code 'SMI-0007-M26'}). Derived purely from the owner's own fields, so both
520	     * {@link #assignCustomerCode} and {@link #defaultRegistrationDate} must run first.
521	     *
522	     * @param owner the owner being created (with its {@code customerCode} and
523	     *              {@code registrationDate} already set)
524	     */
525	    private void assignMembershipNumber(Owner owner) {
526	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
527	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
528	    }
529	
530	    /**
531	     * The number of owners that must already carry a registration date before a subsequent
532	     * create for that same day is flagged with a bulk-signup warning. The warning is raised
533	     * once the count of owners already registered on that day <em>exceeds</em> this value.
534	     */
535	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
536	
537	    /**
538	     * Assigns the owner's {@code bulkSignupWarning} on create: {@code true} when more than
539	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry this owner's (business-day
540	     * adjusted) {@code registrationDate}, otherwise {@code false}. The count is taken over the
541	     * existing owners before this one is persisted, so it reflects only the owners already
542	     * created for that day (matching the accumulation used by {@link #rejectDailyLimit}).
543	     *
544	     * @param owner the owner being created (with its {@code registrationDate} already set)
545	     */
546	    private void assignBulkSignupWarning(Owner owner) {
547	        LocalDate registrationDate = owner.getRegistrationDate();
548	        long count = this.clinicService.findAllOwners().stream()
549	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
550	            .count();
551	        owner.setBulkSignupWarning(count > BULK_SIGNUP_WARNING_THRESHOLD);
552	    }
553	
554	    /**
555	     * Returns the lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
556	     *
557	     * @param value the string to hash
558	     * @return the 64-character lower-case hex digest
559	     */
560	    private static String sha256Hex(String value) {
561	        try {
562	            byte[] digest = MessageDigest.getInstance("SHA-256")
563	                .digest(value.getBytes(StandardCharsets.UTF_8));
564	            StringBuilder sb = new StringBuilder(digest.length * 2);
565	            for (byte b : digest) {
566	                sb.append(String.format("%02x", b));
567	            }
568	            return sb.toString();
569	        }
570	        catch (NoSuchAlgorithmException e) {
571	            throw new IllegalStateException("SHA-256 not available", e);
572	        }
573	    }
574	
575	    /**
576	     * Rejects a create whose lower-cased email is already used by any existing owner. The
577	     * submitted email has already been normalized (trimmed and lower-cased) by
578	     * {@link #normalizeEmail}; each stored owner's email is lower-cased the same way before
579	     * comparison so differing casing still counts as the same email. A {@code null} submitted
580	     * email is skipped, since the field is optional.
581	     *
582	     * @param normalizedEmail the submitted, already-normalized (lower-cased) email, possibly
583	     *                        {@code null}
584	     * @throws DuplicateEmailException with a 409 status if another owner already uses the same
585	     *                                 lower-cased email
586	     */
587	    private void rejectDuplicateEmail(String normalizedEmail) {
588	        if (normalizedEmail == null) {
589	            return;
590	        }
591	        boolean duplicate = this.clinicService.findAllOwners().stream()
592	            .map(Owner::getEmail)
593	            .filter(email -> email != null)
594	            .map(email -> email.toLowerCase(Locale.ROOT))
595	            .anyMatch(normalizedEmail::equals);
596	        if (duplicate) {
597	            throw new DuplicateEmailException(normalizedEmail);
598	        }
599	    }
600	
601	    private void rejectDuplicateTelephone(String normalizedTelephone) {
602	        boolean duplicate = this.clinicService.findAllOwners().stream()
603	            .map(Owner::getTelephone)
604	            .map(OwnerRestControllerV1::toE164)
605	            .filter(telephone -> telephone != null)
606	            .anyMatch(normalizedTelephone::equals);
607	        if (duplicate) {
608	            throw new DuplicateTelephoneException(normalizedTelephone);
609	        }
610	    }
611	
612	    /**
613	     * Rejects a create whose {@code lastName} and {@code address} match those of an existing
614	     * owner. Both fields are compared with {@link #collapse} — trimmed, internal whitespace
615	     * runs collapsed to a single space, and case-insensitive — so differing spacing or casing
616	     * still counts as the same household. The check is skipped when the request opts in via
617	     * {@code sharesHousehold == true}, acknowledging that the new owner shares a household with
618	     * the existing one.
619	     *
620	     * @param ownerFieldsDto the submitted owner fields
621	     * @throws DuplicateHouseholdException with a 409 status if another owner already has the same
622	     *                                     last name and address and the request did not opt in
623	     */
624	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
625	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
626	            return;
627	        }
628	        String lastName = collapse(ownerFieldsDto.getLastName());
629	        String address = collapse(ownerFieldsDto.getAddress());
630	        boolean duplicate = this.clinicService.findAllOwners().stream()
631	            .anyMatch(owner -> collapse(owner.getLastName()).equals(lastName)
632	                && collapse(owner.getAddress()).equals(address));
633	        if (duplicate) {
634	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
635	        }
636	    }
637	
638	    /**
639	     * The maximum number of owners permitted in a single city. A create is rejected once the
640	     * owner's city already contains this many owners.
641	     */
642	    private static final long CITY_CAPACITY = 50;
643	
644	    /**
645	     * Rejects a create whose {@code city} already contains {@link #CITY_CAPACITY} or more owners,
646	     * compared case-insensitively (matching {@link #assignCustomerCode}). The count is taken
647	     * before this owner is persisted.
648	     *
649	     * @param city the submitted city
650	     * @throws CityAtCapacityException with a 409 status if the city is already at capacity
651	     */
652	    private void rejectCityAtCapacity(String city) {
653	        long count = this.clinicService.findAllOwners().stream()
654	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
655	            .count();
656	        if (count >= CITY_CAPACITY) {
657	            throw new CityAtCapacityException(city);
658	        }
659	    }
660	
661	    /**
662	     * The maximum number of owners permitted to be created in a single day. A create is
663	     * rejected once this many owners already carry today's {@code registrationDate}.
664	     */
665	    private static final long DAILY_LIMIT = 100;
666	
667	    /**
668	     * Rejects a create once {@link #DAILY_LIMIT} or more owners already carry the given adjusted
669	     * business day as their {@code registrationDate}. The day counted against is this create's
670	     * effective registration date after the business-day roll (see {@link #defaultRegistrationDate}),
671	     * so owners are counted per adjusted business day. The count is taken before this owner is
672	     * persisted.
673	     *
674	     * @param businessDay the effective, business-day-adjusted registration date of this create
675	     * @throws DailyOwnerLimitExceededException with a 429 status if the day is already at the limit
676	     */
677	    private void rejectDailyLimit(LocalDate businessDay) {
678	        long count = this.clinicService.findAllOwners().stream()
679	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
680	            .count();
681	        if (count >= DAILY_LIMIT) {
682	            throw new DailyOwnerLimitExceededException(businessDay);
683	        }
684	    }
685	
686	    /**
687	     * Canonicalizes a value for household comparison: leading/trailing whitespace is trimmed,
688	     * every internal run of whitespace is collapsed to a single space, and the result is
689	     * lower-cased. A {@code null} value collapses to the empty string.
690	     *
691	     * @param value the value to canonicalize, possibly {@code null}
692	     * @return the collapsed, lower-cased value
693	     */
694	    private static String collapse(String value) {
695	        if (value == null) {
696	            return "";
697	        }
698	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
699	    }
700	
701	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
702	    @Override
703	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
704	        Owner owner = this.clinicService.findOwnerById(ownerId);
705	        if (owner != null) {
706	            Pet pet = owner.getPet(petId);
707	            if (pet != null) {
708	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
709	            }
710	        }
711	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
712	    }
713	}
